## Module 1: Tensor and GPU Memory Management

### Component 1.1: Tensor Structure

Implement complete tensor abstraction with automatic GPU memory management.

```zig
// src/tensor.zig

const std = @import("std");
const cuda = @import("cuda_bindings.zig");

pub const DType = enum {
    f32,
    f16,
    i32,
    i64,
};

pub const Device = enum {
    cpu,
    cuda,
};

pub const Tensor = struct {
    data: ?*anyopaque,
    shape: []usize,
    strides: []usize,
    dtype: DType,
    device: Device,
    allocator: std.mem.Allocator,
    requires_grad: bool,
    grad: ?*Tensor,

    pub fn init(allocator: std.mem.Allocator, shape: []const usize, dtype: DType, device: Device) !*Tensor {
        const tensor = try allocator.create(Tensor);

        const shape_copy = try allocator.alloc(usize, shape.len);
        @memcpy(shape_copy, shape);

        const strides = try allocator.alloc(usize, shape.len);
        var stride: usize = 1;
        var i: usize = shape.len;
        while (i > 0) {
            i -= 1;
            strides[i] = stride;
            stride *= shape[i];
        }

        const total_elements = blk: {
            var total: usize = 1;
            for (shape) |dim| total *= dim;
            break :blk total;
        };

        const bytes_per_element = switch (dtype) {
            .f32 => @sizeOf(f32),
            .f16 => @sizeOf(f16),
            .i32 => @sizeOf(i32),
            .i64 => @sizeOf(i64),
        };

        const total_bytes = total_elements * bytes_per_element;

        const data = switch (device) {
            .cpu => try allocator.alignedAlloc(u8, 64, total_bytes),
            .cuda => blk: {
                var ptr: ?*anyopaque = null;
                const result = cuda.cudaMalloc(@ptrCast(&ptr), total_bytes);
                if (result != cuda.cudaSuccess) return error.CudaAllocationFailed;
                break :blk ptr;
            },
        };

        tensor.* = .{
            .data = data,
            .shape = shape_copy,
            .strides = strides,
            .dtype = dtype,
            .device = device,
            .allocator = allocator,
            .requires_grad = false,
            .grad = null,
        };

        return tensor;
    }

    pub fn deinit(self: *Tensor) void {
        if (self.data) |data| {
            switch (self.device) {
                .cpu => {
                    const bytes = self.numElements() * self.bytesPerElement();
                    const slice: []u8 = @as([*]u8, @ptrCast(data))[0..bytes];
                    self.allocator.free(slice);
                },
                .cuda => {
                    _ = cuda.cudaFree(data);
                },
            }
        }

        self.allocator.free(self.shape);
        self.allocator.free(self.strides);

        if (self.grad) |grad| {
            grad.deinit();
            self.allocator.destroy(grad);
        }

        self.allocator.destroy(self);
    }

    pub fn numElements(self: *const Tensor) usize {
        var total: usize = 1;
        for (self.shape) |dim| total *= dim;
        return total;
    }

    pub fn bytesPerElement(self: *const Tensor) usize {
        return switch (self.dtype) {
            .f32 => @sizeOf(f32),
            .f16 => @sizeOf(f16),
            .i32 => @sizeOf(i32),
            .i64 => @sizeOf(i64),
        };
    }

    pub fn fill(self: *Tensor, value: f32) !void {
        const num_elements = self.numElements();

        switch (self.device) {
            .cpu => {
                const data_f32: [*]f32 = @ptrCast(@alignCast(self.data.?));
                for (0..num_elements) |i| {
                    data_f32[i] = value;
                }
            },
            .cuda => {
                try cuda.fillKernel(self.data.?, value, num_elements);
            },
        }
    }

    pub fn randn(self: *Tensor, mean: f32, std: f32) !void {
        switch (self.device) {
            .cpu => {
                var prng = std.rand.DefaultPrng.init(blk: {
                    var seed: u64 = undefined;
                    std.os.getrandom(std.mem.asBytes(&seed)) catch unreachable;
                    break :blk seed;
                });
                const random = prng.random();

                const data_f32: [*]f32 = @ptrCast(@alignCast(self.data.?));
                const num_elements = self.numElements();

                for (0..num_elements) |i| {
                    const u1 = random.float(f32);
                    const u2 = random.float(f32);
                    const z = @sqrt(-2.0 * @log(u1)) * @cos(2.0 * std.math.pi * u2);
                    data_f32[i] = mean + std * z;
                }
            },
            .cuda => {
                try cuda.randnKernel(self.data.?, mean, std, self.numElements());
            },
        }
    }

    pub fn toCuda(self: *Tensor) !*Tensor {
        if (self.device == .cuda) return self;

        const cuda_tensor = try Tensor.init(self.allocator, self.shape, self.dtype, .cuda);

        const bytes = self.numElements() * self.bytesPerElement();
        const result = cuda.cudaMemcpy(
            cuda_tensor.data.?,
            self.data.?,
            bytes,
            cuda.cudaMemcpyHostToDevice
        );

        if (result != cuda.cudaSuccess) return error.CudaMemcpyFailed;

        return cuda_tensor;
    }

    pub fn toCpu(self: *Tensor) !*Tensor {
        if (self.device == .cpu) return self;

        const cpu_tensor = try Tensor.init(self.allocator, self.shape, self.dtype, .cpu);

        const bytes = self.numElements() * self.bytesPerElement();
        const result = cuda.cudaMemcpy(
            cpu_tensor.data.?,
            self.data.?,
            bytes,
            cuda.cudaMemcpyDeviceToHost
        );

        if (result != cuda.cudaSuccess) return error.CudaMemcpyFailed;

        return cpu_tensor;
    }

    pub fn reshape(self: *Tensor, new_shape: []const usize) !*Tensor {
        const new_elements = blk: {
            var total: usize = 1;
            for (new_shape) |dim| total *= dim;
            break :blk total;
        };

        if (new_elements != self.numElements()) return error.ReshapeMismatch;

        const reshaped = try self.allocator.create(Tensor);
        const shape_copy = try self.allocator.alloc(usize, new_shape.len);
        @memcpy(shape_copy, new_shape);

        const strides = try self.allocator.alloc(usize, new_shape.len);
        var stride: usize = 1;
        var i: usize = new_shape.len;
        while (i > 0) {
            i -= 1;
            strides[i] = stride;
            stride *= new_shape[i];
        }

        reshaped.* = .{
            .data = self.data,
            .shape = shape_copy,
            .strides = strides,
            .dtype = self.dtype,
            .device = self.device,
            .allocator = self.allocator,
            .requires_grad = self.requires_grad,
            .grad = null,
        };

        return reshaped;
    }
};
```

