### Component 1.3: CUDA Kernel Implementations

Implement complete CUDA kernels for all tensor operations.

```cuda
// src/cuda/kernels.cu

#include <cuda_runtime.h>
#include <curand_kernel.h>
#include <cmath>

extern "C" {

__global__ void fillKernelImpl(float* data, float value, size_t n) {
    size_t idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < n) {
        data[idx] = value;
    }
}

cudaError_t fillKernel(void* data, float value, size_t n) {
    const int threads = 256;
    const int blocks = (n + threads - 1) / threads;
    fillKernelImpl<<<blocks, threads>>>((float*)data, value, n);
    return cudaGetLastError();
}

__global__ void randnKernelImpl(float* data, float mean, float std, size_t n, unsigned long long seed) {
    size_t idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < n) {
        curandState state;
        curand_init(seed, idx, 0, &state);
        data[idx] = mean + std * curand_normal(&state);
    }
}

cudaError_t randnKernel(void* data, float mean, float std, size_t n) {
    const int threads = 256;
    const int blocks = (n + threads - 1) / threads;
    unsigned long long seed = 12345ULL; // Should use proper random seed
    randnKernelImpl<<<blocks, threads>>>((float*)data, mean, std, n, seed);
    return cudaGetLastError();
}

__global__ void matmulKernelImpl(const float* A, const float* B, float* C, 
                                  size_t M, size_t N, size_t K) {
    size_t row = blockIdx.y * blockDim.y + threadIdx.y;
    size_t col = blockIdx.x * blockDim.x + threadIdx.x;

    if (row < M && col < N) {
        float sum = 0.0f;
        for (size_t i = 0; i < K; ++i) {
            sum += A[row * K + i] * B[i * N + col];
        }
        C[row * N + col] = sum;
    }
}

cudaError_t matmulKernel(const float* A, const float* B, float* C, 
                         size_t M, size_t N, size_t K) {
    dim3 threads(16, 16);
    dim3 blocks((N + threads.x - 1) / threads.x, (M + threads.y - 1) / threads.y);
    matmulKernelImpl<<<blocks, threads>>>(A, B, C, M, N, K);
    return cudaGetLastError();
}

__global__ void addKernelImpl(const float* A, const float* B, float* C, size_t n) {
    size_t idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < n) {
        C[idx] = A[idx] + B[idx];
    }
}

cudaError_t addKernel(const float* A, const float* B, float* C, size_t n) {
    const int threads = 256;
    const int blocks = (n + threads - 1) / threads;
    addKernelImpl<<<blocks, threads>>>(A, B, C, n);
    return cudaGetLastError();
}

__global__ void reluKernelImpl(const float* input, float* output, size_t n) {
    size_t idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < n) {
        output[idx] = fmaxf(0.0f, input[idx]);
    }
}

cudaError_t reluKernel(const float* input, float* output, size_t n) {
    const int threads = 256;
    const int blocks = (n + threads - 1) / threads;
    reluKernelImpl<<<blocks, threads>>>(input, output, n);
    return cudaGetLastError();
}

__global__ void softmaxKernelImpl(const float* input, float* output, 
                                   size_t batch_size, size_t dim) {
    size_t batch_idx = blockIdx.x;
    if (batch_idx >= batch_size) return;

    const float* batch_input = input + batch_idx * dim;
    float* batch_output = output + batch_idx * dim;

    // Find max for numerical stability
    float max_val = batch_input[0];
    for (size_t i = 1; i < dim; ++i) {
        max_val = fmaxf(max_val, batch_input[i]);
    }

    // Compute exp and sum
    float sum = 0.0f;
    for (size_t i = 0; i < dim; ++i) {
        batch_output[i] = expf(batch_input[i] - max_val);
        sum += batch_output[i];
    }

    // Normalize
    for (size_t i = 0; i < dim; ++i) {
        batch_output[i] /= sum;
    }
}

cudaError_t softmaxKernel(const float* input, float* output, 
                          size_t batch_size, size_t dim) {
    softmaxKernelImpl<<<batch_size, 1>>>(input, output, batch_size, dim);
    return cudaGetLastError();
}

__global__ void layerNormKernelImpl(const float* input, float* output,
                                     const float* gamma, const float* beta,
                                     size_t batch_size, size_t dim, float eps) {
    size_t batch_idx = blockIdx.x;
    if (batch_idx >= batch_size) return;

    const float* batch_input = input + batch_idx * dim;
    float* batch_output = output + batch_idx * dim;

    // Compute mean
    float mean = 0.0f;
    for (size_t i = 0; i < dim; ++i) {
        mean += batch_input[i];
    }
    mean /= dim;

    // Compute variance
    float variance = 0.0f;
    for (size_t i = 0; i < dim; ++i) {
        float diff = batch_input[i] - mean;
        variance += diff * diff;
    }
    variance /= dim;

    // Normalize
    float std_inv = 1.0f / sqrtf(variance + eps);
    for (size_t i = 0; i < dim; ++i) {
        float normalized = (batch_input[i] - mean) * std_inv;
        batch_output[i] = gamma[i] * normalized + beta[i];
    }
}

cudaError_t layerNormKernel(const float* input, float* output,
                            const float* gamma, const float* beta,
                            size_t batch_size, size_t dim, float eps) {
    layerNormKernelImpl<<<batch_size, 1>>>(input, output, gamma, beta, 
                                            batch_size, dim, eps);
    return cudaGetLastError();
}

