## Module 2: Tensor Operations

### Component 2.1: Matrix Operations

```zig
// src/ops.zig

const std = @import("std");
const Tensor = @import("tensor.zig").Tensor;
const cuda = @import("cuda_bindings.zig");

pub fn matmul(allocator: std.mem.Allocator, a: *Tensor, b: *Tensor) !*Tensor {
    if (a.shape.len != 2 or b.shape.len != 2) return error.InvalidDimensions;
    if (a.shape[1] != b.shape[0]) return error.DimensionMismatch;

    const M = a.shape[0];
    const K = a.shape[1];
    const N = b.shape[1];

    const result_shape = [_]usize{ M, N };
    const result = try Tensor.init(allocator, &result_shape, .f32, a.device);

    switch (a.device) {
        .cpu => {
            const a_data: [*]f32 = @ptrCast(@alignCast(a.data.?));
            const b_data: [*]f32 = @ptrCast(@alignCast(b.data.?));
            const c_data: [*]f32 = @ptrCast(@alignCast(result.data.?));

            for (0..M) |i| {
                for (0..N) |j| {
                    var sum: f32 = 0.0;
                    for (0..K) |k| {
                        sum += a_data[i * K + k] * b_data[k * N + j];
                    }
                    c_data[i * N + j] = sum;
                }
            }
        },
        .cuda => {
            const a_data: *f32 = @ptrCast(@alignCast(a.data.?));
            const b_data: *f32 = @ptrCast(@alignCast(b.data.?));
            const c_data: *f32 = @ptrCast(@alignCast(result.data.?));

            const err = cuda.matmulKernel(a_data, b_data, c_data, M, N, K);
            if (err != .cudaSuccess) return error.CudaKernelFailed;
        },
    }

    return result;
}

pub fn add(allocator: std.mem.Allocator, a: *Tensor, b: *Tensor) !*Tensor {
    if (!std.mem.eql(usize, a.shape, b.shape)) return error.ShapeMismatch;

    const result = try Tensor.init(allocator, a.shape, a.dtype, a.device);
    const n = a.numElements();

    switch (a.device) {
        .cpu => {
            const a_data: [*]f32 = @ptrCast(@alignCast(a.data.?));
            const b_data: [*]f32 = @ptrCast(@alignCast(b.data.?));
            const c_data: [*]f32 = @ptrCast(@alignCast(result.data.?));

            for (0..n) |i| {
                c_data[i] = a_data[i] + b_data[i];
            }
        },
        .cuda => {
            const a_data: *f32 = @ptrCast(@alignCast(a.data.?));
            const b_data: *f32 = @ptrCast(@alignCast(b.data.?));
            const c_data: *f32 = @ptrCast(@alignCast(result.data.?));

            const err = cuda.addKernel(a_data, b_data, c_data, n);
            if (err != .cudaSuccess) return error.CudaKernelFailed;
        },
    }

    return result;
}

pub fn relu(allocator: std.mem.Allocator, input: *Tensor) !*Tensor {
    const output = try Tensor.init(allocator, input.shape, input.dtype, input.device);
    const n = input.numElements();

    switch (input.device) {
        .cpu => {
            const in_data: [*]f32 = @ptrCast(@alignCast(input.data.?));
            const out_data: [*]f32 = @ptrCast(@alignCast(output.data.?));

            for (0..n) |i| {
                out_data[i] = @max(0.0, in_data[i]);
            }
        },
        .cuda => {
            const in_data: *f32 = @ptrCast(@alignCast(input.data.?));
            const out_data: *f32 = @ptrCast(@alignCast(output.data.?));

            const err = cuda.reluKernel(in_data, out_data, n);
            if (err != .cudaSuccess) return error.CudaKernelFailed;
        },
    }

    return output;
}

pub fn softmax(allocator: std.mem.Allocator, input: *Tensor, dim: usize) !*Tensor {
    if (input.shape.len != 2) return error.InvalidDimensions;

    const batch_size = input.shape[0];
    const feature_dim = input.shape[1];

    const output = try Tensor.init(allocator, input.shape, input.dtype, input.device);

    switch (input.device) {
        .cpu => {
            const in_data: [*]f32 = @ptrCast(@alignCast(input.data.?));
            const out_data: [*]f32 = @ptrCast(@alignCast(output.data.?));

            for (0..batch_size) |b| {
                const offset = b * feature_dim;

                // Find max for numerical stability
                var max_val = in_data[offset];
                for (1..feature_dim) |i| {
                    max_val = @max(max_val, in_data[offset + i]);
                }

                // Compute exp and sum
                var sum: f32 = 0.0;
                for (0..feature_dim) |i| {
                    const exp_val = @exp(in_data[offset + i] - max_val);
                    out_data[offset + i] = exp_val;
                    sum += exp_val;
                }

                // Normalize
                for (0..feature_dim) |i| {
                    out_data[offset + i] /= sum;
                }
            }
        },
        .cuda => {
            const in_data: *f32 = @ptrCast(@alignCast(input.data.?));
            const out_data: *f32 = @ptrCast(@alignCast(output.data.?));

            const err = cuda.softmaxKernel(in_data, out_data, batch_size, feature_dim);
            if (err != .cudaSuccess) return error.CudaKernelFailed;
        },
    }

    return output;
}
```

