    out_features: usize,
    allocator: std.mem.Allocator,

    pub fn init(allocator: std.mem.Allocator, in_features: usize, out_features: usize, device: @import("../tensor.zig").Device) !*Linear {
        const layer = try allocator.create(Linear);

        const weight_shape = [_]usize{ out_features, in_features };
        const bias_shape = [_]usize{out_features};

        const weight = try Tensor.init(allocator, &weight_shape, .f32, device);
        const bias = try Tensor.init(allocator, &bias_shape, .f32, device);

        // Xavier initialization
        const std_dev = @sqrt(2.0 / @as(f32, @floatFromInt(in_features + out_features)));
        try weight.randn(0.0, std_dev);
        try bias.fill(0.0);

        weight.requires_grad = true;
        bias.requires_grad = true;

        layer.* = .{
            .weight = weight,
            .bias = bias,
            .in_features = in_features,
            .out_features = out_features,
            .allocator = allocator,
        };

        return layer;
    }

    pub fn deinit(self: *Linear) void {
        self.weight.deinit();
        self.bias.deinit();
        self.allocator.destroy(self);
    }

    pub fn forward(self: *Linear, input: *Tensor) !*Tensor {
        // input: [batch, in_features]
        // weight: [out_features, in_features]
        // output: [batch, out_features]

        const batch_size = input.shape[0];
        const output_shape = [_]usize{ batch_size, self.out_features };

        // Compute input @ weight^T
        const weight_t = try self.weight.transpose(self.allocator);
        defer weight_t.deinit();

        var output = try ops.matmul(self.allocator, input, weight_t);

        // Add bias (broadcast)
        const bias_expanded = try self.expandBias(batch_size);
        defer bias_expanded.deinit();

        const result = try ops.add(self.allocator, output, bias_expanded);
        output.deinit();

        return result;
    }

    fn expandBias(self: *Linear, batch_size: usize) !*Tensor {
        const expanded_shape = [_]usize{ batch_size, self.out_features };
        const expanded = try Tensor.init(self.allocator, &expanded_shape, .f32, self.bias.device);

        const bias_data: [*]f32 = @ptrCast(@alignCast(self.bias.data.?));
        const expanded_data: [*]f32 = @ptrCast(@alignCast(expanded.data.?));

        for (0..batch_size) |b| {
            for (0..self.out_features) |i| {
                expanded_data[b * self.out_features + i] = bias_data[i];
            }
        }

        return expanded;
    }
};
