```zig
// src/nn/attention.zig

const std = @import("std");
const Tensor = @import("../tensor.zig").Tensor;
const Linear = @import("linear.zig").Linear;
const ops = @import("../ops.zig");

pub const MultiHeadAttention = struct {
    num_heads: usize,
    head_dim: usize,
    embed_dim: usize,

    q_proj: *Linear,
    k_proj: *Linear,
    v_proj: *Linear,
    out_proj: *Linear,

    allocator: std.mem.Allocator,

    pub fn init(allocator: std.mem.Allocator, embed_dim: usize, num_heads: usize, device: @import("../tensor.zig").Device) !*MultiHeadAttention {
        if (embed_dim % num_heads != 0) return error.InvalidHeadDimension;

        const attn = try allocator.create(MultiHeadAttention);
        const head_dim = embed_dim / num_heads;

        attn.* = .{
            .num_heads = num_heads,
            .head_dim = head_dim,
            .embed_dim = embed_dim,
            .q_proj = try Linear.init(allocator, embed_dim, embed_dim, device),
            .k_proj = try Linear.init(allocator, embed_dim, embed_dim, device),
            .v_proj = try Linear.init(allocator, embed_dim, embed_dim, device),
            .out_proj = try Linear.init(allocator, embed_dim, embed_dim, device),
            .allocator = allocator,
        };

        return attn;
    }

    pub fn deinit(self: *MultiHeadAttention) void {
        self.q_proj.deinit();
        self.k_proj.deinit();
        self.v_proj.deinit();
        self.out_proj.deinit();
        self.allocator.destroy(self);
    }

    pub fn forward(self: *MultiHeadAttention, query: *Tensor, key: *Tensor, value: *Tensor) !*Tensor {
        const batch_size = query.shape[0];
        const seq_len = query.shape[1];

        // Project Q, K, V
        var Q = try self.q_proj.forward(query);
        defer Q.deinit();
        var K = try self.k_proj.forward(key);
        defer K.deinit();
        var V = try self.v_proj.forward(value);
        defer V.deinit();

        // Reshape to [batch, num_heads, seq_len, head_dim]
        const qkv_shape = [_]usize{ batch_size, seq_len, self.num_heads, self.head_dim };

        Q = try Q.reshape(&qkv_shape);
        K = try K.reshape(&qkv_shape);
        V = try V.reshape(&qkv_shape);

        // Transpose to [batch, num_heads, seq_len, head_dim]
        Q = try Q.permute(self.allocator, &[_]usize{ 0, 2, 1, 3 });
        K = try K.permute(self.allocator, &[_]usize{ 0, 2, 1, 3 });
        V = try V.permute(self.allocator, &[_]usize{ 0, 2, 1, 3 });

        // Scaled dot-product attention
        // scores = Q @ K^T / sqrt(head_dim)
        const K_t = try K.transpose(self.allocator);
        defer K_t.deinit();

        var scores = try ops.matmul(self.allocator, Q, K_t);
        defer scores.deinit();

        const scale = 1.0 / @sqrt(@as(f32, @floatFromInt(self.head_dim)));
        try scores.scalarMul(scale);

        // Softmax
        var attn_weights = try ops.softmax(self.allocator, scores, scores.shape.len - 1);
        defer attn_weights.deinit();

        // Apply attention to values
        var context = try ops.matmul(self.allocator, attn_weights, V);
        defer context.deinit();

        // Transpose back and reshape
        context = try context.permute(self.allocator, &[_]usize{ 0, 2, 1, 3 });
        const output_shape = [_]usize{ batch_size, seq_len, self.embed_dim };
        context = try context.reshape(&output_shape);

        // Output projection
        const output = try self.out_proj.forward(context);

        return output;
    }
};
