```zig
// src/nn/riemannian.zig

const std = @import("std");
const Tensor = @import("../tensor.zig").Tensor;
const Linear = @import("linear.zig").Linear;
const ops = @import("../ops.zig");

pub const RiemannianProjection = struct {
    in_dim: usize,
    out_dim: usize,
    linear: *Linear,
    curvature: *Tensor,
    allocator: std.mem.Allocator,

    pub fn init(allocator: std.mem.Allocator, in_dim: usize, out_dim: usize, device: @import("../tensor.zig").Device) !*RiemannianProjection {
        const proj = try allocator.create(RiemannianProjection);

        const curvature_shape = [_]usize{1};
        const curvature = try Tensor.init(allocator, &curvature_shape, .f32, device);
        try curvature.fill(1.0);
        curvature.requires_grad = true;

        proj.* = .{
            .in_dim = in_dim,
            .out_dim = out_dim,
            .linear = try Linear.init(allocator, in_dim, out_dim, device),
            .curvature = curvature,
            .allocator = allocator,
        };

        return proj;
    }

    pub fn deinit(self: *RiemannianProjection) void {
        self.linear.deinit();
        self.curvature.deinit();
        self.allocator.destroy(self);
    }

    pub fn forward(self: *RiemannianProjection, x_euclidean: *Tensor) !*Tensor {
        // Project to tangent space
        var v = try self.linear.forward(x_euclidean);
        defer v.deinit();

        // Compute norm
        const v_norm = try self.computeNorm(v);
        defer v_norm.deinit();

        // Exponential map: sinh(κ||v||) * v / (κ||v||)
        const kappa_data: [*]f32 = @ptrCast(@alignCast(self.curvature.data.?));
        const kappa = kappa_data[0];

        const v_data: [*]f32 = @ptrCast(@alignCast(v.data.?));
        const norm_data: [*]f32 = @ptrCast(@alignCast(v_norm.data.?));

        const z_hyperbolic = try Tensor.init(self.allocator, v.shape, .f32, v.device);
        const z_data: [*]f32 = @ptrCast(@alignCast(z_hyperbolic.data.?));

        const batch_size = v.shape[0];
        const dim = v.shape[1];

        for (0..batch_size) |b| {
            const norm = norm_data[b] + 1e-8;
            const sinh_val = @sinh(kappa * norm);
            const scale = sinh_val / (kappa * norm);

            for (0..dim) |d| {
                const idx = b * dim + d;
                z_data[idx] = scale * v_data[idx];
            }
        }

        return z_hyperbolic;
    }

    fn computeNorm(self: *RiemannianProjection, tensor: *Tensor) !*Tensor {
        const batch_size = tensor.shape[0];
        const dim = tensor.shape[1];

        const norm_shape = [_]usize{batch_size};
        const norm = try Tensor.init(self.allocator, &norm_shape, .f32, tensor.device);

        const tensor_data: [*]f32 = @ptrCast(@alignCast(tensor.data.?));
        const norm_data: [*]f32 = @ptrCast(@alignCast(norm.data.?));

        for (0..batch_size) |b| {
            var sum: f32 = 0.0;
            for (0..dim) |d| {
                const val = tensor_data[b * dim + d];
                sum += val * val;
            }
            norm_data[b] = @sqrt(sum);
        }

        return norm;
    }
};
