### Component 4.2: PDE Geometric Flow Solver

```zig
// src/nn/geometric_flow.zig

const std = @import("std");
const Tensor = @import("../tensor.zig").Tensor;
const ops = @import("../ops.zig");

pub const GeometricFlowSolver = struct {
    latent_dim: usize,
    num_steps: usize,
    dt: f32,
    diffusion_coeff: *Tensor,
    reaction_coeff: *Tensor,
    allocator: std.mem.Allocator,

    pub fn init(allocator: std.mem.Allocator, latent_dim: usize, num_steps: usize, device: @import("../tensor.zig").Device) !*GeometricFlowSolver {
        const solver = try allocator.create(GeometricFlowSolver);

        const coeff_shape = [_]usize{1};
        const diffusion_coeff = try Tensor.init(allocator, &coeff_shape, .f32, device);
        const reaction_coeff = try Tensor.init(allocator, &coeff_shape, .f32, device);

        try diffusion_coeff.fill(0.1);
        try reaction_coeff.fill(1.0);

        diffusion_coeff.requires_grad = true;
        reaction_coeff.requires_grad = true;

        solver.* = .{
            .latent_dim = latent_dim,
            .num_steps = num_steps,
            .dt = 1.0 / @as(f32, @floatFromInt(num_steps)),
            .diffusion_coeff = diffusion_coeff,
            .reaction_coeff = reaction_coeff,
            .allocator = allocator,
        };

        return solver;
    }

    pub fn deinit(self: *GeometricFlowSolver) void {
        self.diffusion_coeff.deinit();
        self.reaction_coeff.deinit();
        self.allocator.destroy(self);
    }

    pub fn forward(self: *GeometricFlowSolver, z_initial: *Tensor, metric: *Tensor) !*Tensor {
        var z_current = try z_initial.clone(self.allocator);

        for (0..self.num_steps) |_| {
            const z_next = try self.reactionDiffusionStep(z_current, metric);
            z_current.deinit();
            z_current = z_next;
        }

        return z_current;
    }

    fn reactionDiffusionStep(self: *GeometricFlowSolver, z: *Tensor, metric: *Tensor) !*Tensor {
        // Compute Laplacian using metric tensor
        const laplacian = try self.computeLaplacian(z, metric);
        defer laplacian.deinit();

        // Reaction term: z - z^3
        const z_squared = try ops.elementwiseMul(self.allocator, z, z);
        defer z_squared.deinit();

        const z_cubed = try ops.elementwiseMul(self.allocator, z_squared, z);
        defer z_cubed.deinit();

        const reaction = try ops.sub(self.allocator, z, z_cubed);
        defer reaction.deinit();

        // Get coefficients
        const diff_data: [*]f32 = @ptrCast(@alignCast(self.diffusion_coeff.data.?));
        const react_data: [*]f32 = @ptrCast(@alignCast(self.reaction_coeff.data.?));
        const diff_coeff = diff_data[0];
        const react_coeff = react_data[0];

        // Weighted sum
        const diff_term = try laplacian.clone(self.allocator);
        try diff_term.scalarMul(diff_coeff);
        defer diff_term.deinit();

        const react_term = try reaction.clone(self.allocator);
        try react_term.scalarMul(react_coeff);
        defer react_term.deinit();

        const update = try ops.add(self.allocator, diff_term, react_term);
        defer update.deinit();

        // Scale by dt
        try update.scalarMul(self.dt);

        // z_next = z + dt * update
        const z_next = try ops.add(self.allocator, z, update);

        return z_next;
    }

    fn computeLaplacian(self: *GeometricFlowSolver, z: *Tensor, metric: *Tensor) !*Tensor {
        // Simplified finite difference Laplacian
        // In production, should use metric tensor properly

        const batch_size = z.shape[0];
        const dim = z.shape[1];

        const laplacian = try Tensor.init(self.allocator, z.shape, .f32, z.device);
        const z_data: [*]f32 = @ptrCast(@alignCast(z.data.?));
        const lap_data: [*]f32 = @ptrCast(@alignCast(laplacian.data.?));

        // Simple discrete Laplacian: -4z[i] + z[i-1] + z[i+1] + z[i-dim] + z[i+dim]
        for (0..batch_size) |b| {
            for (0..dim) |d| {
                const idx = b * dim + d;
                var sum: f32 = -4.0 * z_data[idx];

                if (d > 0) sum += z_data[idx - 1];
                if (d < dim - 1) sum += z_data[idx + 1];
                if (b > 0) sum += z_data[(b-1) * dim + d];
                if (b < batch_size - 1) sum += z_data[(b+1) * dim + d];

                lap_data[idx] = sum;
            }
        }

        return laplacian;
    }
};
